import java.util.concurrent.*;
import java.util.Map;
import java.util.HashMap;
import java.util.regex.Pattern;
import java.util.regex.Matcher;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.List;
import java.util.ArrayList;

public class BlockchainOracle {

    private final ExecutorService executor = Executors.newFixedThreadPool(4);
    private final Map<String, String> contractState = new ConcurrentHashMap<>();
    private final Map<String, CompletableFuture<String>> pendingQueries = new ConcurrentHashMap<>();
    private static final Pattern SAFE_IDENTIFIER = Pattern.compile("^[a-zA-Z0-9_.-]+$");
    private static final Pattern SHELL_META = Pattern.compile("[;&|`$(){}\\\"'<>\\n\\r]");

    public CompletableFuture<String> executeSmartContract(String contractId, String method, Map<String, String> params) {
        return CompletableFuture.supplyAsync(() -> {
            validateContractId(contractId);
            return resolveMethod(contractId, method, params);
        }, executor).thenComposeAsync(intermediate -> {
            return processOracleCallback(contractId, intermediate, params);
        }, executor);
    }

    private void validateContractId(String contractId) {
        if (contractId == null || contractId.length() > 64) {
            throw new SecurityException("Invalid contract ID");
        }
        if (!SAFE_IDENTIFIER.matcher(contractId).matches()) {
            throw new SecurityException("Contract ID contains invalid characters");
        }
    }

    private String resolveMethod(String contractId, String method, Map<String, String> params) {
        switch (method) {
            case "queryPrice":
                return buildPriceQuery(params.getOrDefault("asset", "ETH"));
            case "verifyIdentity":
                return buildIdentityQuery(params.getOrDefault("subject", ""));
            case "executeCallback":
                return buildCallbackPayload(contractId, params);
            default:
                throw new IllegalArgumentException("Unknown method: " + method);
        }
    }

    private String buildPriceQuery(String asset) {
        String sanitized = sanitizeInput(asset);
        return "PRICE_QUERY:" + sanitized;
    }

    private String buildIdentityQuery(String subject) {
        String sanitized = sanitizeInput(subject);
        return "IDENTITY_QUERY:" + sanitized;
    }

    private String buildCallbackPayload(String contractId, Map<String, String> params) {
        String callbackData = params.getOrDefault("callbackData", "");
        String encodedData = encodeForTransport(callbackData);
        return "CALLBACK:" + contractId + ":" + encodedData;
    }

    private String sanitizeInput(String input) {
        if (input == null) return "";
        if (input.length() > 128) {
            input = input.substring(0, 128);
        }
        Matcher m = SHELL_META.matcher(input);
        if (m.find()) {
            throw new SecurityException("Input contains prohibited characters");
        }
        return input;
    }

    private String encodeForTransport(String data) {
        if (data == null) return "";
        // Base64-like encoding for transport safety
        byte[] bytes = data.getBytes(StandardCharsets.UTF_8);
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b & 0xFF));
        }
        return sb.toString();
    }

    private String decodeFromTransport(String encoded) {
        if (encoded == null || encoded.isEmpty()) return "";
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < encoded.length() - 1; i += 2) {
            String hex = encoded.substring(i, i + 2);
            sb.append((char) Integer.parseInt(hex, 16));
        }
        return sb.toString();
    }

    private CompletableFuture<String> processOracleCallback(String contractId, String intermediate, Map<String, String> params) {
        return CompletableFuture.supplyAsync(() -> {
            if (intermediate.startsWith("CALLBACK:")) {
                return handleCallbackExecution(intermediate, params);
            } else if (intermediate.startsWith("PRICE_QUERY:")) {
                return executePriceOracle(intermediate);
            } else if (intermediate.startsWith("IDENTITY_QUERY:")) {
                return executeIdentityOracle(intermediate);
            }
            return "ERROR:UNKNOWN_INTERMEDIATE";
        }, executor);
    }

    private String handleCallbackExecution(String intermediate, Map<String, String> params) {
        // Parse: CALLBACK:<contractId>:<hexEncodedData>
        String[] parts = intermediate.split(":", 3);
        if (parts.length < 3) {
            return "ERROR:MALFORMED_CALLBACK";
        }
        String callbackContractId = parts[1];
        String encodedPayload = parts[2];

        // Decode the transport-encoded payload
        String decodedPayload = decodeFromTransport(encodedPayload);

        // The callback type determines execution path
        String callbackType = params.getOrDefault("callbackType", "internal");

        if ("external".equals(callbackType)) {
            return executeExternalCallback(callbackContractId, decodedPayload);
        } else {
            return executeInternalCallback(callbackContractId, decodedPayload);
        }
    }

    private String executeInternalCallback(String contractId, String payload) {
        contractState.put(contractId + ".lastCallback", payload);
        return "OK:INTERNAL:" + computeHash(payload);
    }

    private String executeExternalCallback(String contractId, String payload) {
        // External callbacks invoke the oracle verification daemon
        // contractId is already validated, payload was hex-decoded from user input
        // Re-validate the decoded payload before use
        String safePayload = payload.replaceAll("[^a-zA-Z0-9_.:/=-]", "");

        // Build the verification command using ProcessBuilder with argument array
        // Note: contractId was validated with SAFE_IDENTIFIER pattern earlier
        List<String> command = new ArrayList<>();
        command.add("oracle-verify");
        command.add("--contract");
        command.add(contractId);
        command.add("--data");
        command.add(safePayload);
        command.add("--mode");
        command.add("strict");

        return executeSystemCommand(command);
    }

    private String executePriceOracle(String query) {
        String asset = query.substring("PRICE_QUERY:".length());
        // Simulated price lookup
        contractState.put("lastPriceQuery", asset);
        return "PRICE:" + asset + ":" + (Math.random() * 10000);
    }

    private String executeIdentityOracle(String query) {
        String subject = query.substring("IDENTITY_QUERY:".length());
        contractState.put("lastIdentityQuery", subject);
        return "IDENTITY:" + subject + ":VERIFIED";
    }

    private String executeSystemCommand(List<String> command) {
        Process process = null;
        try {
            ProcessBuilder pb = new ProcessBuilder(command);
            pb.redirectErrorStream(true);
            process = pb.start();
            boolean finished = process.waitFor(5, TimeUnit.SECONDS);
            if (!finished) {
                // Prevent resource leak / hung child process (DoS)
                process.destroyForcibly();
                return "ERROR:EXECUTION_TIMEOUT";
            }
            byte[] output = process.getInputStream().readAllBytes();
            return new String(output, StandardCharsets.UTF_8).trim();
        } catch (Exception e) {
            return "ERROR:EXECUTION_FAILED";
        } finally {
            if (process != null && process.isAlive()) {
                process.destroyForcibly();
            }
        }
    }

    private String computeHash(String input) {
        try {
            MessageDigest md = MessageDigest.getInstance("SHA-256");
            byte[] hash = md.digest(input.getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder();
            for (byte b : hash) {
                sb.append(String.format("%02x", b & 0xFF));
            }
            return sb.toString();
        } catch (Exception e) {
            return "HASH_ERROR";
        }
    }

    public static void main(String[] args) throws Exception {
        BlockchainOracle oracle = new BlockchainOracle();

        Map<String, String> params = new HashMap<>();
        params.put("callbackData", "test-verification-data");
        params.put("callbackType", "external");

        CompletableFuture<String> result = oracle.executeSmartContract(
            "contract_abc123", "executeCallback", params
        );

        System.out.println("Result: " + result.get(10, TimeUnit.SECONDS));
        oracle.executor.shutdown();
    }
}
